do $do$
declare run_id bigint; rid bigint; a bigint; b bigint; r record; k int;
begin
insert into public.companies(name,entity_type) select v.n,v.t from (values ($q$CATL$q$,$q$public_company$q$),($q$Panasonic$q$,$q$public_company$q$),($q$Samsung$q$,$q$public_company$q$),($q$xAI$q$,$q$private_company$q$)) v(n,t) where not exists (select 1 from public.companies c where lower(c.name)=lower(v.n));
create temp table _q(i int primary key, t text) on commit drop;
insert into _q values (1,$q$As discussed in Part II, Item 9B, Other Information—xAI Investment of this Annual Report on Form 10-K, the Company entered into an agreement in January 2026 to make a minority equity investment.$q$),(2,$q$Currently, we rely on suppliers such as Panasonic and Contemporary Amperex Technology Co. Limited (CATL) for these cells.$q$),(3,$q$During the year ended December 31, 2025, we recognized $
430
 million of revenues and $
285
 million of cost of revenues from xAI for its purchase of our Megapack products in the ordinary course of business.$q$),(4,$q$In 2025, we further expanded Cortex, our training cluster at Gigafactory Texas, and announced a new collaboration with Samsung to manufacture advanced semiconductors for AI inference and training in the U.S.$q$),(5,$q$On January 16, 2026, following review in a manner consistent with the Board’s fiduciary duties and the Company’s related party transactions policy (the “RPT Policy”), Tesla entered into an agreement to invest approximately $2 billion to acquire shares of Series E Preferred Stock of xAI as part of xAI’s recent publicly-disclosed financing round.$q$);
create temp table _e(n int, ty text, s text, g text, qs int[], sec text[], pct numeric, qual text, basis text, note text) on commit drop;
insert into _e values (1,$q$partners$q$,$q$TSLA$q$,$q$Samsung$q$,$q${4}$q$::int[],$q${business}$q$::text[],null,null,null,null),(2,$q$supplies$q$,$q$Panasonic$q$,$q$TSLA$q$,$q${2}$q$::int[],$q${risk_factors}$q$::text[],null,null,null,null),(3,$q$supplies$q$,$q$CATL$q$,$q$TSLA$q$,$q${2}$q$::int[],$q${risk_factors}$q$::text[],null,null,null,null),(4,$q$invests$q$,$q$TSLA$q$,$q$xAI$q$,$q${1,5}$q$::int[],$q${mdna,notes}$q$::text[],null,null,null,null),(5,$q$sells_to$q$,$q$TSLA$q$,$q$xAI$q$,$q${3}$q$::int[],$q${notes}$q$::text[],null,null,null,null);
create or replace function pg_temp.nid(l text) returns bigint language sql as $f$ select id from public.companies where case l  when $q$TSLA$q$ then ticker=$q$TSLA$q$ else lower(name)=lower(l) end order by id limit 1 $f$;
insert into public.agent_runs(agent_name,mode,target,model,tokens_in,tokens_out,cost_usd,status,review_status) values ('filings_extraction','batch',$q$TSLA M6 group 2-4$q$,'claude-sonnet-5-5',203421,1635,0.5981,'completed','unreviewed') returning id into run_id;
for r in select * from _e order by n loop a := pg_temp.nid(r.s); b := pg_temp.nid(r.g); if r.ty in ('competes','partners') and a > b then rid := a; a := b; b := rid; end if; rid := null; select id into rid from public.relationships where source_id=a and target_id=b and relationship_type=r.ty order by id limit 1; if rid is null then insert into public.relationships(source_id,target_id,relationship_type,exposure_pct,exposure_qualifier,exposure_basis,exposure_as_of,source_type,status,run_id,as_of_date,note) values (a,b,r.ty,r.pct,r.qual,case when r.pct is null then 'none' else r.basis end,case when r.pct is null then null else '2025-12-31'::date end,'sec_filing','staged',run_id,'2025-12-31',r.note) returning id into rid; end if; if (select status from public.relationships where id=rid)='staged' then for k in 1..array_length(r.qs,1) loop insert into public.evidence(relationship_id,document_url,section,quote,quote_found,published_at) select rid,$q$https://www.sec.gov/Archives/edgar/data/1318605/000162828026003952/tsla-20251231.htm$q$,r.sec[k],t,true,$q$2026-01-29$q$ from _q where i=r.qs[k]; end loop; end if; end loop;
end $do$;
